virtual-proxy.diagram:
classDiagram
  class Image {
    <<interface>>
    +display()
  }
  class ProxyImage {
    -String file
    -RealImage real
    +display()
  }
  class RealImage {
    -data
    +RealImage(file)
    +display()
  }
  Image <|.. ProxyImage
  Image <|.. RealImage
  ProxyImage --> RealImage : 첫 display() 시 생성·위임
  Client --> Image

virtual-proxy.pseudocode:
class RealImage:
    def __init__(self, file):
        self.data = load_from_disk(file)  # 생성 비용 큼
    def display(self):
        render(self.data)

class ProxyImage:  # RealImage와 같은 인터페이스
    def __init__(self, file):
        self.file = file
        self.real = None  # 아직 생성 안 함
    def display(self):
        if self.real is None:  # 첫 사용 시점에 생성
            self.real = RealImage(self.file)
        self.real.display()  # 이후 실제 객체에 위임

visitor-pattern.diagram:
classDiagram
  class Visitor {
    <<interface>>
    +visitNumber(Number n)
    +visitAdd(Add a)
  }
  class Element {
    <<interface>>
    +accept(Visitor v)
  }
  class Number {
    +accept(Visitor v)
  }
  class Add {
    +accept(Visitor v)
  }
  Element <|.. Number
  Element <|.. Add
  Add o-- Element : left·right
  Visitor <|.. EvalVisitor
  Visitor <|.. PrintVisitor
  Number ..> Visitor : v.visitNumber(this)
  Client ..> Element : accept(visitor)

visitor-pattern.pseudocode:
class Number:
    def __init__(self, v):
        self.v = v
    def accept(self, visitor):  # 1차 디스패치: 요소 타입
        return visitor.visit_number(self)

class Add:
    def __init__(self, l, r):
        self.l, self.r = l, r
    def accept(self, visitor):
        return visitor.visit_add(self)

class EvalVisitor:  # 새 연산 = 새 방문자 클래스
    def visit_number(self, n):  # 2차: 방문자 타입
        return n.v
    def visit_add(self, a):
        return a.l.accept(self) + a.r.accept(self)

class PrintVisitor:  # 요소 클래스는 수정 없음
    def visit_number(self, n):
        return str(n.v)
    def visit_add(self, a):
        return f'({a.l.accept(self)}+{a.r.accept(self)})'
